package com.example.orchestrator;
import java.util.*;
public class WorkflowGraph {private final LinkedHashMap<String,WorkflowNode> nodes=new LinkedHashMap<>();public WorkflowGraph add(WorkflowNode n){nodes.put(n.id(),n);return this;}public Collection<WorkflowNode> nodes(){return nodes.values();}public WorkflowNode node(String id){return Objects.requireNonNull(nodes.get(id));}public void validate(){for(var n:nodes.values())for(String d:n.dependencies())if(!nodes.containsKey(d))throw new IllegalArgumentException("unknown dependency "+d);topological();}public List<List<WorkflowNode>> levels(){Map<String,Integer> indegree=new HashMap<>();nodes.values().forEach(n->indegree.put(n.id(),n.dependencies().size()));List<List<WorkflowNode>> result=new ArrayList<>();Set<String> done=new HashSet<>();while(done.size()<nodes.size()){List<WorkflowNode> level=nodes.values().stream().filter(n->!done.contains(n.id())&&n.dependencies().stream().allMatch(done::contains)).toList();if(level.isEmpty())throw new IllegalArgumentException("workflow graph contains a cycle");result.add(level);level.forEach(n->done.add(n.id()));}return result;}private void topological(){levels();}}
